请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-076

=== 用户原始指令 (query.txt) ===
弄个专注模式卡片，背景来点睡眠音乐的柔和渐变，上面用专注库的耳机图标和大号字写上'开始沉浸式专注'。下面用文字字符图标横向排几个选项，比如番茄钟、白噪音、冥想，每个选项底色稍微分一下区。底部弄个大按钮点了直接能跳到系统设置里的应用时长限制里去。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个专注模式卡片，背景来点睡眠音乐的柔和渐变，上面用专注库的耳机图标和大号字写上'开始沉浸式专注'。下面用文字字符图标横向排几个选项，比如番茄钟、白噪音、冥想，每个选项底色稍微分一下区。底部弄个大按钮点了直接能跳到系统设置里的应用时长限制里去。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModel": {
    "value": {
      "focus": {
        "title": "开始沉浸式专注",
        "subtitle": "睡眠音乐轻柔铺底",
        "icon": "resources/base/media/icon_earphone.png",
        "options": [
          {
            "glyph": "25",
            "label": "番茄钟"
          },
          {
            "glyph": "Hz",
            "label": "白噪音"
          },
          {
            "glyph": "静",
            "label": "冥想"
          }
        ],
        "actionText": "设置应用时长"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "earphone_icon",
      "src": "resources/base/media/icon_earphone.png",
      "use": "focus audio icon",
      "description": "素材库耳机图标，可用于专注模式中表达佩戴耳机、播放睡眠音乐或白噪音的状态。",
      "bindTo": "/focus/icon"
    }
  ]
}

